test("指し先の型が未知なら、locking を指していても違反にしない", () => {
  const violation = ComponentBinding.violation(
    components(),
    ComponentBinding.create("button", {
      node: "button-frame",
      prop: "locking",
    }),
  );

  expect(violation).toEqual(Option.none);
});

test("内部のプリミティブの locking を指す binding は unbindable-prop になる", () => {
  const violation = ComponentBinding.violation(
    components(),
    ComponentBinding.create("button", {
      node: "button-label",
      prop: "locking",
    }),
  );

  expect(violation).toEqual(Option.some({ kind: "unbindable-prop" }));
});

test("部品の根の locking を指す binding も unbindable-prop になる", () => {
  const violation = ComponentBinding.violation(
    components(),
    ComponentBinding.create("button", { node: "button", prop: "locking" }),
  );

  expect(violation).toEqual(Option.some({ kind: "unbindable-prop" }));
});

test("指し先のインスタンスの参照先が locking という名前の公開 prop を content に繋いでいれば、違反にならない", () => {
  const components: ComponentSet = {
    card: {
      type: "Box",
      children: [{ name: "card-badge", ref: "badge" }],
    },
    badge: {
      type: "Box",
      children: [{ name: "badge-label", type: "Text" }],
      publicProps: { locking: { node: "badge-label", prop: "content" } },
    },
  };

  const violation = ComponentBinding.violation(
    components,
    ComponentBinding.create("card", { node: "card-badge", prop: "locking" }),
  );

  expect(violation).toEqual(Option.none);
});

test("参照先が locking を公開していなければ、インスタンス自身のロックへは繋がらず missing-public-prop になる", () => {
  const components: ComponentSet = {
    card: {
      type: "Box",
      children: [{ name: "card-badge", ref: "badge", locking: "locked" }],
    },
    badge: {
      type: "Box",
      children: [{ name: "badge-label", type: "Text" }],
    },
  };

  const violation = ComponentBinding.violation(
    components,
    ComponentBinding.create("card", { node: "card-badge", prop: "locking" }),
  );

  expect(violation).toEqual(
    Option.some({ kind: "missing-public-prop", ref: "badge" }),
  );
});

test("locking を指す binding は解決できない", () => {
  const components: ComponentSet = {
    button: { type: "Box", children: [{ name: "button-label", type: "Text" }] },
  };

  const target = ComponentBinding.resolvePropTarget(
    components,
    ComponentBinding.create("button", {
      node: "button-label",
      prop: "locking",
    }),
  );

  expect(target).toEqual(Option.none);
});

test("連鎖の先で locking に着く binding は解決できない", () => {
  const components: ComponentSet = {
    button: {
      type: "Box",
      children: [{ name: "button-label", type: "Text" }],
      publicProps: { lock: { node: "button-label", prop: "locking" } },
    },
    card: {
      type: "Box",
      children: [{ name: "card-action", ref: "button" }],
      publicProps: { actionLock: { node: "card-action", prop: "lock" } },
    },
  };

  const target = ComponentBinding.resolvePropTarget(
    components,
    ComponentBinding.create("card", {
      node: "card-action",
      prop: "lock",
    }),
  );

  expect(target).toEqual(Option.none);
});

test("locking への binding は unbindable-binding-prop エラーになる", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    components: {
      button: {
        type: "Box",
        children: [{ name: "button-label", type: "Text" }],
        publicProps: { lock: { node: "button-label", prop: "locking" } },
      },
    },
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "unbindable-binding-prop",
      nodeName: "button",
      prop: "lock",
    }),
  ]);
});

test("入れ子の部品の locking へ繋いだ公開 prop を親が辿っていても、エラーは繋いだ部品に 1 件だけ出る", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    components: {
      button: {
        type: "Box",
        children: [{ name: "button-label", type: "Text" }],
        publicProps: { lock: { node: "button-label", prop: "locking" } },
      },
      card: {
        type: "Box",
        children: [{ name: "card-action", ref: "button" }],
        publicProps: { actionLock: { node: "card-action", prop: "lock" } },
      },
    },
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "unbindable-binding-prop",
      nodeName: "button",
      prop: "lock",
    }),
  ]);
});

test("locking という名前の公開 prop を他の prop へ繋いでもエラーにならない", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    components: {
      badge: {
        type: "Box",
        children: [{ name: "badge-label", type: "Text" }],
        publicProps: { locking: { node: "badge-label", prop: "content" } },
      },
    },
  });

  expect(DesignDocument.collectErrors(document)).toEqual([]);
});

test("インスタンスが語彙に無い値で locking へ繋いだ公開 prop を上書きしていても、エラーは binding の 1 件だけ", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    components: {
      button: {
        type: "Box",
        children: [{ name: "button-label", type: "Text" }],
        publicProps: { lock: { node: "button-label", prop: "locking" } },
      },
    },
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [
          {
            name: "screen-button",
            ref: "button",
            overrides: { lock: "frozen" },
          },
        ],
      },
    ],
  });

  const errors = DesignDocument.collectErrors(document);

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "unbindable-binding-prop",
      nodeName: "button",
      prop: "lock",
    }),
  ]);
});

test("locking へ binding したときのエラーは、部品名と公開 prop 名の位置で、ノード名と prop 名を挙げる", () => {
  const errors = errorsOf(
    {
      button: {
        type: "Box",
        children: [{ name: "button-label", type: "Text" }],
        publicProps: { lock: { node: "button-label", prop: "locking" } },
      },
    },
    [],
  );

  expect(errors).toStrictEqual([
    {
      kind: "unbindable-binding-prop",
      nodeName: "button",
      prop: "lock",
      message:
        'prop "locking" of node "button-label" cannot be bound to a public prop',
    },
  ]);
});

test("locking へ繋いだ公開 prop はコントロールが出ず、同じ部品の他の公開 prop は出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "lock-card",
  });

  expect(publicPropNames(selection)).toEqual(["title"]);
});
